// Recurring expenses, built from the transactions the user logged with
// "isRecurring" + "frequency". A series = same description (or category) +
// same frequency. Two consumers:
//   getUpcomingRecurring: what is coming up soon (reminder card)
//   getDueRecurring:      occurrences whose date has arrived and are not yet
//                         logged; the app books them automatically.
// Booked copies carry autoGenerated: true and a deterministic id
// (rec_<seriesHash>_<date>), so two members opening the app at once write the
// same document instead of creating a duplicate.
const PERIOD_DAYS = { weekly: 7, monthly: 30, yearly: 365 }
const DAY_MS = 86400000

const startOfDay = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate())
function parseDate(s) {
  const [y, m, d] = s.split('-').map(Number)
  return new Date(y, m - 1, d)
}
const daysBetween = (a, b) => Math.round((startOfDay(b) - startOfDay(a)) / DAY_MS)
const fmtDate = (d) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`

// date of the n-th occurrence after `anchor`, keeping the day of month (clamped to month end)
function addPeriods(anchor, frequency, n) {
  if (frequency === 'weekly') return new Date(anchor.getFullYear(), anchor.getMonth(), anchor.getDate() + 7 * n)
  const months = frequency === 'yearly' ? 12 * n : n
  const first = new Date(anchor.getFullYear(), anchor.getMonth() + months, 1)
  const lastDay = new Date(first.getFullYear(), first.getMonth() + 1, 0).getDate()
  return new Date(first.getFullYear(), first.getMonth(), Math.min(anchor.getDate(), lastDay))
}

export const seriesKey = (tx) =>
  `${(tx.description || '').trim().toLowerCase() || tx.category}|${tx.frequency}`

// short stable hash (djb2) so a series can be used safely inside Firestore ids / field paths
export function seriesHash(key) {
  let h = 5381
  for (let i = 0; i < key.length; i++) h = ((h * 33) ^ key.charCodeAt(i)) >>> 0
  return h.toString(36)
}

// All recurring-expense series found in the transactions.
export function buildSeries(transactions) {
  const groups = new Map()
  transactions.forEach(tx => {
    if (tx.type !== 'expense' || !tx.isRecurring || !PERIOD_DAYS[tx.frequency] || !tx.date) return
    const key = seriesKey(tx)
    if (!groups.has(key)) groups.set(key, [])
    groups.get(key).push(tx)
  })
  const out = []
  groups.forEach((txs, key) => {
    const byDate = [...txs].sort((a, b) => b.date.localeCompare(a.date))
    const latest = byDate[0]
    // the day-of-month comes from what the person logged, not from booked copies
    const anchor = byDate.find(t => !t.autoGenerated) || latest
    out.push({
      key,
      hash: seriesHash(key),
      name: (latest.description || '').trim(),
      category: latest.category,
      amount: latest.amount || 0,
      frequency: latest.frequency,
      latest,
      anchorDate: parseDate(anchor.date),
      dates: txs.map(t => parseDate(t.date)),
    })
  })
  return out
}

// an occurrence counts as already logged if an entry sits within half a period of it
const isLogged = (s, due) =>
  s.dates.some(d => Math.abs(daysBetween(d, due)) < PERIOD_DAYS[s.frequency] / 2)

// Recurring expenses due in the next `withinDays` days and not logged yet.
// With auto-booking on, "today" is excluded: it gets booked on app open.
export function getUpcomingRecurring(transactions, today = new Date(), withinDays = 7, { stopped = {}, includeToday = true } = {}) {
  const now = startOfDay(today)
  const out = []
  buildSeries(transactions).forEach(s => {
    if (stopped[s.hash]) return
    let n = 1
    let due = addPeriods(s.anchorDate, s.frequency, n)
    while ((includeToday ? due < now : due <= now) && n < 400) { n += 1; due = addPeriods(s.anchorDate, s.frequency, n) }
    const daysUntil = daysBetween(now, due)
    if (daysUntil > withinDays || isLogged(s, due)) return
    out.push({
      key: s.key, hash: s.hash, name: s.name, category: s.category,
      amount: s.amount, frequency: s.frequency, due, daysUntil,
    })
  })
  return out.sort((a, b) => a.daysUntil - b.daysUntil)
}

// Occurrences whose date has arrived (<= today) and are not logged yet, at most
// `maxBackDays` back so an abandoned series cannot flood the month.
export function getDueRecurring(transactions, today = new Date(), { stopped = {}, skipped = {}, maxBackDays = 90 } = {}) {
  const now = startOfDay(today)
  const out = []
  buildSeries(transactions).forEach(s => {
    if (stopped[s.hash]) return
    for (let n = 1; n < 400; n++) {
      const due = addPeriods(s.anchorDate, s.frequency, n)
      if (due > now) break
      if (daysBetween(due, now) > maxBackDays) continue
      const date = fmtDate(due)
      const id = `rec_${s.hash}_${date}`
      if (skipped[id] || isLogged(s, due)) continue
      const { id: _id, createdAt: _c, date: _d, ...rest } = s.latest
      out.push({ id, data: { ...rest, date, isRecurring: true, frequency: s.frequency, autoGenerated: true } })
    }
  })
  return out
}
